import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';import syncFs from 'node:fs';import {parseEnv} from 'node:util';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';import {SESv2Client,SendEmailCommand,GetAccountCommand,GetSuppressedDestinationCommand} from '@aws-sdk/client-sesv2';
for(const[k,v]of Object.entries(parseEnv(syncFs.readFileSync('.env.ses.local','utf8'))))if(k.startsWith('AWS_')||k.startsWith('SES_'))process.env[k]=v;
const{db,base,headers}=await import('./reply-runtime-20261015.mjs');const{reserveAction}=await import('../lib/partnership-core/reserve.mjs');const dir='artifacts/partnership-nudges-20261019';const p=JSON.parse(await fs.readFile(dir+'/send-plan.json'))[0];const prior=JSON.parse(await fs.readFile(dir+'/receipt-'+p.id+'.json'));assert(prior.error?.startsWith('404 '));
const[c]=await db('market_contacts',{id:'eq.'+p.id});const email='Angeladumont@tailoredroomshomestaging.com';assert.equal(c.email,email);const peers=await db('market_contacts',{email:'ilike.'+email});assert(peers.every(x=>!x.do_not_contact&&!x.cross_channel_suppressed_at&&!x.email_unsubscribed_at&&!['bounced','complained','unsubscribed'].includes(x.email_status)));
const latest=await db('market_touches',{contact_id:'eq.'+p.id,order:'created_at.desc',limit:'1'});assert.equal(latest[0].id,'55925edc-dd35-4298-8e8a-a77916279831');const reserved=await db('partnership_action_reservations',{contact_id:'eq.'+p.id,channel:'eq.email',created_at:'gte.2026-10-19T00:00:00Z'});assert.equal(reserved.length,0,'Existing exposure; reconcile first');
const ses=new SESv2Client({region:process.env.AWS_REGION||'us-east-2',maxAttempts:1});const health=await ses.send(new GetAccountCommand({}));assert(health.SendingEnabled&&health.ProductionAccessEnabled&&health.EnforcementStatus==='HEALTHY');try{await ses.send(new GetSuppressedDestinationCommand({EmailAddress:email}));throw Error('SES suppressed');}catch(e){if(e.name!=='NotFoundException')throw e;}
const file=dir+'/angela-ses-receipt.json';const sender='John | Saturn Star Movers <john@saturnstarmovers.ca>';const key='staging-gentle-nudge-20261019:'+p.id;await fs.writeFile(file,JSON.stringify({state:'reserved_no_blind_retry',at:new Date().toISOString(),plan:p,route404_reconciled:true},null,2),{flag:'wx'});await reserveAction({url:base,headers,contactId:p.id,channel:'email',kind:'reply',key,content:p.subject+'\n'+p.body,sender,emailProvider:'ses'});
const h=createHash('sha256').update(key).digest('hex');const tid=[h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20,32)].join('-');const metadata={source:'owner_requested_contextual_nudge',from:sender,to:email,subject:p.subject,reply_to:'business@starmovers.ca',delivery_state:'reserved',provider:'ses'};await db('market_touches',{},'POST',{id:tid,contact_id:p.id,channel:'email',direction:'outbound',notes:'Subject: '+p.subject+'\n\n'+p.body,metadata});const result=await ses.send(new SendEmailCommand({FromEmailAddress:sender,ReplyToAddresses:['business@starmovers.ca'],Destination:{ToAddresses:[email]},ConfigurationSetName:process.env.AWS_SES_CONFIGURATION_SET||undefined,EmailTags:[{Name:'contact_id',Value:p.id}],Content:{Simple:{Subject:{Data:p.subject,Charset:'UTF-8'},Body:{Text:{Data:p.body,Charset:'UTF-8'}}}}}));assert(result.MessageId);await fs.writeFile(file,JSON.stringify({state:'accepted',at:new Date().toISOString(),plan:p,messageId:result.MessageId},null,2));await db('market_touches',{id:'eq.'+tid},'PATCH',{metadata:{...metadata,provider_message_id:result.MessageId,delivery_state:'accepted'}});await db('market_contacts',{id:'eq.'+p.id},'PATCH',{email_last_sent_at:new Date().toISOString(),last_touch_at:new Date().toISOString(),preferred_channel:'email',sequence_paused:true,sequence_paused_reason:'Owner requested one gentle contextual nudge; await reply',next_follow_up:null});const[t]=await db('market_touches',{id:'eq.'+tid});assert.equal(t.metadata.provider_message_id,result.MessageId);await fs.writeFile(file,JSON.stringify({state:'accepted_crm_verified',at:new Date().toISOString(),plan:p,messageId:result.MessageId,touch_id:tid},null,2));console.log(JSON.stringify({name:c.name,channel:'email',accepted:true,crm_verified:true}));
